
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;

namespace JuliHyro.Event.Lib.core.Debug;

/// <summary>
/// Stores messages generated by the library, including their source methods.
/// </summary>
public class CodeReturn
{
    private static readonly object SyncRoot = new();

    private static readonly Dictionary<string, List<CodeReturnMessage>> MSG = new()
    {
        ["Info"] = new List<CodeReturnMessage>(),
        ["Warning"] = new List<CodeReturnMessage>(),
        ["Error"] = new List<CodeReturnMessage>(),
        ["Success"] = new List<CodeReturnMessage>()
    };

    /// <summary>
    /// Adds an informational message.
    /// </summary>
    /// <param name="message">The message to store.</param>
    internal static void AddInfo(string message)
    {
        AddMessage("Info", message);
    }

    /// <summary>
    /// Adds an error message.
    /// </summary>
    /// <param name="message">The message to store.</param>
    internal static void AddError(string message)
    {
        AddMessage("Error", message);
    }

    /// <summary>
    /// Adds a warning message.
    /// </summary>
    /// <param name="message">The message to store.</param>
    internal static void AddWarning(string message)
    {
        AddMessage("Warning", message);
    }

    /// <summary>
    /// Adds a success message.
    /// </summary>
    /// <param name="message">The message to store.</param>
    internal static void AddSuccess(string message)
    {
        AddMessage("Success", message);
    }

    /// <summary>
    /// Stores a message together with its type and caller path.
    /// </summary>
    /// <param name="type">The type of message to store.</param>
    /// <param name="message">The message content.</param>
    private static void AddMessage(string type, string message)
    {
        StackFrame? Frame = new StackTrace(2, false).GetFrame(0);
        var Method = Frame?.GetMethod();

        string CallerPath = Method?.DeclaringType?.FullName is string ClassName
            ? $"{ClassName}.{Method.Name}"
            : Method?.Name ?? "Unknown";

        lock (SyncRoot)
        {
            MSG[type].Add(new CodeReturnMessage(
                type,
                message,
                CallerPath
            ));
        }
    }

    /// <summary>
    /// Gets the messages stored for the specified type.
    /// </summary>
    /// <param name="type">The message type: Info, Warning, Error, or Success.</param>
    /// <returns>A read-only snapshot of the messages, or an empty list if the type is unknown.</returns>
    public static IReadOnlyList<string> GetMessages(string type)
    {
        lock (SyncRoot)
        {
            if (MSG.TryGetValue(type, out List<CodeReturnMessage>? messages))
            {
                return messages.Select(entry => entry.Message).ToArray();
            }

            return Array.Empty<string>();
        }
    }

    /// <summary>
    /// Gets all messages generated by the specified method.
    /// </summary>
    /// <param name="method">The method name or its full caller path.</param>
    /// <returns>A read-only snapshot of matching messages, including their types and caller paths.</returns>
    public static IReadOnlyList<CodeReturnMessage> GetMessagesByMethod(string method)
    {
        if (String.IsNullOrWhiteSpace(method))
        {
            return Array.Empty<CodeReturnMessage>();
        }

        lock (SyncRoot)
        {
            return MSG.Values
                .SelectMany(messages => messages)
                .Where(entry =>
                    String.Equals(entry.CallerPath, method, StringComparison.Ordinal)
                    || entry.CallerPath.EndsWith(
                        "." + method,
                        StringComparison.Ordinal
                    ))
                .ToArray();
        }
    }
}

/// <summary>
/// Contains a message and information about where it originated.
/// </summary>
/// <param name="Type">The message type: Info, Warning, Error, or Success.</param>
/// <param name="Message">The message content.</param>
/// <param name="CallerPath">The full path of the class and method that created the message.</param>
public sealed record CodeReturnMessage(
    string Type,
    string Message,
    string CallerPath
);
